def validate_topics(topics, exam_name):
    print(f"Validating {len(topics)} topics for {exam_name}...")
    assert len(topics) == 100, f"Expected 100 topics for {exam_name}, got {len(topics)}"
    seen_titles = set()
    for idx, (title, subj, sys_name, key, ref, url) in enumerate(topics, 1):
        assert subj in TAXONOMY_SUBJECTS, f"Invalid subject '{subj}' in {exam_name} #{idx}"
        assert sys_name in TAXONOMY_SYSTEMS, f"Invalid system '{sys_name}' in {exam_name} #{idx}"
        assert len(key) >= 30, f"Key too short in {exam_name} #{idx}"
        assert len(ref) >= 10, f"Ref too short in {exam_name} #{idx}"
        assert url.startswith("https://"), f"Invalid url '{url}' in {exam_name} #{idx}"
        assert title not in seen_titles, f"Duplicate title in {exam_name} #{idx}: {title}"
        seen_titles.add(title)
    print(f"  All 100 topics for {exam_name} validated successfully!")

if __name__ == "__main__":
    validate_topics(MRCEM_TOPICS, "MRCEM")
    validate_topics(SMLE_TOPICS, "SMLE")

    output_path = os.path.join(os.path.dirname(__file__), "mega74_topics_a.py")
    with open(output_path, "w", encoding="utf-8") as f:
        f.write("# scripts/mega74_topics_a.py\n")
        f.write("# Generated topics for MRCEM (100) and SMLE (100)\n\n")
        f.write("MRCEM_TOPICS = " + repr(MRCEM_TOPICS) + "\n\n")
        f.write("SMLE_TOPICS = " + repr(SMLE_TOPICS) + "\n")
    print(f"Successfully wrote {output_path}!")
